ALTER TABLE "drawings" DROP CONSTRAINT "drawings_kind_check";--> statement-breakpoint
ALTER TABLE "drawings" DROP CONSTRAINT "drawings_stamp_fields_check";--> statement-breakpoint
ALTER TABLE "drawings" ADD CONSTRAINT "drawings_kind_check" CHECK ("drawings"."kind" in ('FREEHAND', 'STAMP', 'TEXTURE'));--> statement-breakpoint
ALTER TABLE "drawings" ADD CONSTRAINT "drawings_stamp_fields_check" CHECK (("drawings"."kind" = 'FREEHAND' and "drawings"."stamp_asset_key" is null and "drawings"."stamp_pack_id" is null and "drawings"."stamp_size" is null and "drawings"."stamp_rotation" is null and "drawings"."stamp_layer" is null) or ("drawings"."kind" = 'STAMP' and "drawings"."stamp_asset_key" is not null and (("drawings"."stamp_pack_id" = 'builtin-terrain-v1' and "drawings"."stamp_asset_key" ~ '^[a-z][a-z0-9-]{0,39}$') or ("drawings"."stamp_pack_id" = 'campaign-image' and "drawings"."stamp_asset_key" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')) and "drawings"."stamp_size" is not null and "drawings"."stamp_size" between 16 and 1024 and "drawings"."stamp_rotation" is not null and "drawings"."stamp_rotation" between -360 and 360 and "drawings"."stamp_layer" is not null and "drawings"."stamp_layer" in ('PUBLIC', 'GM')) or ("drawings"."kind" = 'TEXTURE' and "drawings"."stamp_asset_key" is not null and (("drawings"."stamp_pack_id" = 'builtin-texture-v1' and "drawings"."stamp_asset_key" ~ '^[a-z][a-z0-9-]{0,39}$') or ("drawings"."stamp_pack_id" = 'campaign-image' and "drawings"."stamp_asset_key" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')) and "drawings"."stamp_size" is not null and "drawings"."stamp_size" between 16 and 1024 and "drawings"."stamp_rotation" is not null and "drawings"."stamp_rotation" between -360 and 360 and "drawings"."stamp_layer" is not null and "drawings"."stamp_layer" in ('PUBLIC', 'GM') and "drawings"."stroke_width" between 8 and 400));